import sailpoint.object.*;

  import org.apache.log4j.Logger;

  Logger log = Logger.getLogger("iiq.alpha.Alpha-Rule-ActiveDirectory ProvisionPolicy UPN Calculation Rule");
  log.debug("Alpha-Rule-ActiveDirectory UPN Calculation Rule - STARTS");

boolean createPrivilegeAccount = false;

//Get createPrivilegeAccount property from context which is set in Account selector rule for privilege account creation

if(null != context.getProperty("createPrivilegeAccount"))
{
  log.debug("Alpha-Rule-ActiveDirectory UPN Calculation Rule - context :"+context);
  createPrivilegeAccount = Boolean.parseBoolean(context.getProperty("createPrivilegeAccount"));
  log.debug("createPrivilegeAccount"+createPrivilegeAccount );
}


  String firstName = "";
  String lastName = "";
  String fullName = "";
  //Remove all the characters except a-z and A-Z in First Name and Last Name
  if(null != identity.getLastname())
  {
    lastName = identity.getLastname();
    lastName = lastName.replaceAll("[^a-zA-Z]","");
  }
  log.debug("lastName :"+lastName);
  if(null != identity.getFirstname())
  {
    firstName = identity.getFirstname();
    firstName = firstName.replaceAll("[^a-zA-Z]","");


//Check createPrivilegeAccount value is true and prefix with "pa_" to differentiate privileged account

    if(createPrivilegeAccount)
       firstName = "pa_"+firstName ;

    fullName = firstName.concat(lastName);
  }
  log.debug("firstName : "+firstName);
    log.debug("fullName : "+fullName );

  /* 
	*sAMAccountName must be less than 20 chars. ->>check the length of fullName, if the length is more than 19, remove the extraCharCount form the *lastName.
  If lastName is not as long as extraCharCount,remove the extraCharCount from firstName.
	*/ 
  int fullNameLength=fullName.length();
  log.debug("fullNameLength : "+fullNameLength);
  if (fullNameLength > 19 )
  {
    int extraCharCount=fullNameLength-19;
    log.debug("extraCharCount"+extraCharCount);
    int lastNameLength=lastName.length();
    int firstNameLength=firstName.length();
    log.debug("lastNameLength"+lastNameLength);

    if (lastNameLength > extraCharCount )
    {
      lastName=lastName.substring(0,lastNameLength-extraCharCount);
      log.debug("lastname"+lastName);
    }else{
      firstName=firstName.substring(0,firstNameLength-extraCharCount);
      log.debug("firstName"+firstName);						
    }
  } 

  Map upnMap = generateUniqueUPN(firstName,lastName);
  String upn = upnMap.get("userPrincipalName");
  
  log.debug("upn"+upn);
   log.debug("Alpha-Rule-ActiveDirectory UPN Calculation Rule - ENDS");
  
  return upn;
